def test_let_and_use():
    assert run("let x = 5; print(x);") == "5\n"
    assert run("let x = 1; let y = x + 1; print(y);") == "2\n"


def test_shadowing_inside_block_does_not_affect_outer():
    src = """
let x = 1;
{
  let x = 99;
  print(x);
}
print(x);
"""
    assert run(src) == "99\n1\n"


